import Fastify from 'fastify'
import { readdir } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { join } from 'node:path'

export type MarkdownFile = { source: 'Pi' | 'Claude'; path: string }
export const fixtureRoot = fileURLToPath(new URL('../fixtures/', import.meta.url))

// Only regular files/directories are followed; symlinks cannot escape the fixtures.
export async function listMarkdownFiles(root = fixtureRoot): Promise<MarkdownFile[]> {
  const files: MarkdownFile[] = []
  async function walk(directory: string, source: MarkdownFile['source'], prefix = '') {
    const entries = await readdir(directory, { withFileTypes: true })
    entries.sort((a, b) => a.name.localeCompare(b.name))
    for (const entry of entries) {
      const path = prefix ? `${prefix}/${entry.name}` : entry.name
      if (entry.isDirectory()) await walk(join(directory, entry.name), source, path)
      else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
        files.push({ source, path })
      }
    }
  }
  await walk(join(root, 'pi'), 'Pi')
  await walk(join(root, 'claude'), 'Claude')
  return files
}

export function createApp(root = fixtureRoot) {
  const app = Fastify({ logger: true })
  app.get('/api/files', async (_request, reply) => {
    try {
      return { files: await listMarkdownFiles(root) }
    } catch (error) {
      app.log.error(error, 'Fixture listing failed')
      return reply.code(500).send({ error: 'Unable to list Markdown files. Check that both fixture folders are readable.' })
    }
  })
  return app
}

import { createApp } from './app.ts'

const app = createApp()
try {
  await app.listen({ port: 3001, host: '127.0.0.1' })
} catch (error) {
  app.log.error(error)
  process.exitCode = 1
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.once(signal, () => { void app.close() })
}

import { useEffect, useState } from 'react'
import './App.css'

type MarkdownFile = { source: 'Pi' | 'Claude'; path: string }
type ListingState =
  | { status: 'loading' }
  | { status: 'ready'; files: MarkdownFile[] }
  | { status: 'error' }

function App() {
  const [state, setState] = useState<ListingState>({ status: 'loading' })

  useEffect(() => {
    const controller = new AbortController()
    async function load() {
      try {
        const response = await fetch('/api/files', { signal: controller.signal })
        if (!response.ok) throw new Error('Listing failed')
        const data = await response.json() as { files: MarkdownFile[] }
        if (!controller.signal.aborted) setState({ status: 'ready', files: data.files })
      } catch {
        if (!controller.signal.aborted) setState({ status: 'error' })
      }
    }
    void load()
    return () => controller.abort()
  }, [])

  return (
    <main>
      <h1>MD Manager</h1>
      <p>Markdown files in the Pi and Claude fixtures. Paths are relative to each source folder.</p>
      {state.status === 'loading' && <p role="status">Loading Markdown files…</p>}
      {state.status === 'error' && (
        <p role="alert">Unable to load Markdown files. Check that the API is running and both fixture folders are readable, then reload the page.</p>
      )}
      {state.status === 'ready' && (state.files.length === 0
        ? <p role="status">No Markdown files found in the Pi or Claude fixture folders.</p>
        : <>
            <p role="status">{state.files.length} Markdown files</p>
            <table>
              <caption>Available Markdown files</caption>
              <thead><tr><th scope="col">Source</th><th scope="col">Relative path</th></tr></thead>
              <tbody>{state.files.map(file => (
                <tr key={`${file.source}/${file.path}`}>
                  <td>{file.source}</td><td><code>{file.path}</code></td>
                </tr>
              ))}</tbody>
            </table>
          </>)}
    </main>
  )
}

export default App

