import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtemp, mkdir, rm, symlink, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createApp } from './app.ts'

const expected = [
  { source: 'Pi', path: 'skills/review.md' },
  { source: 'Pi', path: 'workflow.md' },
  { source: 'Claude', path: 'empty.md' },
  { source: 'Claude', path: 'subagents/implementer.md' },
  { source: 'Claude', path: 'workflow.md' },
]

test('API lists exactly all five fixture Markdown files, including empty/nested files', async () => {
  const app = createApp()
  try {
    const response = await app.inject('/api/files')
    assert.equal(response.statusCode, 200)
    assert.deepEqual(response.json(), { files: expected })
    assert.equal((await app.inject('/api/files?root=/tmp')).body, response.body)
  } finally { await app.close() }
})

test('empty folders, symlink exclusion, and unreadable/missing source errors', async () => {
  const root = await mkdtemp(join(tmpdir(), 'md-manager-test-'))
  const app = createApp(root)
  try {
    await mkdir(join(root, 'pi'))
    await mkdir(join(root, 'claude'))
    await writeFile(join(root, 'outside.md'), 'Not in a source folder')
    await symlink(join(root, 'outside.md'), join(root, 'pi', 'linked.md'))
    await symlink(root, join(root, 'claude', 'linked-directory'))
    const empty = await app.inject('/api/files')
    assert.equal(empty.statusCode, 200)
    assert.deepEqual(empty.json(), { files: [] })
    await rm(join(root, 'claude'), { recursive: true })
    const failed = await app.inject('/api/files')
    assert.equal(failed.statusCode, 500)
    assert.match(failed.json().error, /both fixture folders are readable/)
    assert.ok(!failed.body.includes(root))
  } finally {
    await app.close()
    await rm(root, { recursive: true, force: true })
  }
})

import { defineConfig } from '@playwright/test'

export default defineConfig({
  testDir: './tests',
  use: { baseURL: 'http://127.0.0.1:5173', browserName: 'chromium' },
  webServer: {
    command: 'npm run dev',
    url: 'http://127.0.0.1:5173',
    reuseExistingServer: false,
    timeout: 30_000,
  },
})

import { test, expect } from '@playwright/test'

test('real app lists all five files with source-relative paths', async ({ page, request }) => {
  await expect.poll(async () => (await request.get('http://127.0.0.1:3001/api/files')).status()).toBe(200)
  await page.goto('/')
  await expect(page.getByRole('status')).toHaveText('5 Markdown files')
  const rows = page.locator('tbody tr')
  await expect(rows).toHaveCount(5)
  const expected = [
    ['Pi', 'skills/review.md'], ['Pi', 'workflow.md'],
    ['Claude', 'empty.md'], ['Claude', 'subagents/implementer.md'], ['Claude', 'workflow.md'],
  ]
  for (const [index, cells] of expected.entries()) {
    await expect(rows.nth(index).locator('td')).toHaveText(cells)
  }
  await expect(page.getByText('notes.txt')).toHaveCount(0)
})

test('loading then empty state', async ({ page }) => {
  let release!: () => void
  const wait = new Promise<void>(resolve => { release = resolve })
  await page.route('**/api/files', async route => {
    await wait
    await route.fulfill({ json: { files: [] } })
  })
  await page.goto('/')
  await expect(page.getByRole('status')).toHaveText('Loading Markdown files…')
  release()
  await expect(page.getByRole('status')).toHaveText('No Markdown files found in the Pi or Claude fixture folders.')
  await expect(page.getByRole('table')).toHaveCount(0)
})

for (const failure of ['http', 'network']) {
  test(`${failure} error gives recovery guidance`, async ({ page }) => {
    await page.route('**/api/files', route => failure === 'http'
      ? route.fulfill({ status: 500, json: { error: 'Listing failed' } })
      : route.abort())
    await page.goto('/')
    await expect(page.getByRole('alert')).toContainText('Unable to load Markdown files.')
    await expect(page.getByRole('alert')).toContainText('reload the page')
    await expect(page.getByRole('table')).toHaveCount(0)
  })
}

